// Parse the LLM response and structure the data
const llmResponse = $input.first().json;
let extractedData;

try {
  // Try to parse JSON from the LLM response
  const content = llmResponse.message?.content || llmResponse.text || JSON.stringify(llmResponse);
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  extractedData = jsonMatch ? JSON.parse(jsonMatch[0]) : {};
} catch (e) {
  extractedData = { raw_text: llmResponse, parse_error: e.message };
}

// Build the structured output
const output = {
  metadata: {
    extraction_date: new Date().toISOString(),
    source_type: "pdf",
    workflow_version: "1.0.0"
  },
  raw_data: {
    fund_info: extractedData.fund_info || {},
    performance_data: extractedData.performance_data || {},
    fees: extractedData.fees || {},
    assets: extractedData.assets || {},
    raw_text_sections: extractedData.raw_text_sections || []
  },
  analysis: {
    risks: extractedData.risks || [],
    opportunities: extractedData.opportunities || []
  }
};

return [{ json: output }];

// Generate HTML for Opportunities and Risks Analysis
const data = $input.first().json;

const generateAnalysisHTML = (title, items, type) => {
  const colorClass = type === 'risk' ? 'risk-item' : 'opportunity-item';
  const icon = type === 'risk' ? '⚠️' : '✅';

  let itemsHTML = '';
  if (Array.isArray(items) && items.length > 0) {
    items.forEach((item, index) => {
      const severity = item.severity || item.impact || 'medium';
      const description = item.description || item.text || (typeof item === 'string' ? item : JSON.stringify(item));
      const category = item.category || 'general';

      itemsHTML += `
        <div class="analysis-item ${colorClass}" data-severity="${severity}">
          <div class="item-header">
            <span class="item-icon">${icon}</span>
            <span class="item-number">#${index + 1}</span>
            <span class="item-category">${category}</span>
            <span class="severity-badge ${severity}">${severity}</span>
          </div>
          <div class="item-content">
            <p class="item-description">${description}</p>
            ${item.recommendation ? `<p class="item-recommendation"><strong>המלצה:</strong> ${item.recommendation}</p>` : ''}
            ${item.data_points ? `<p class="item-data"><strong>נתונים תומכים:</strong> ${JSON.stringify(item.data_points)}</p>` : ''}
          </div>
        </div>
      `;
    });
  } else {
    itemsHTML = '<p class="no-items">לא נמצאו פריטים בקטגוריה זו</p>';
  }

  return `
    <section class="analysis-section ${type}-section">
      <h2>${title}</h2>
      <div class="items-container">
        ${itemsHTML}
      </div>
    </section>
  `;
};

const html = `
